using Greyhaven.Content;
using Greyhaven.Server;
using System.Text.Json;
var root=Path.GetFullPath(args[0]);using var p=new ContentPackage(root);var world=new OriginalWorld(p);int count=0;
void Assert(bool ok,string message="Assertion failed"){if(!ok)throw new Exception(message);}
void Test(string name,Action body){body();count++;Console.WriteLine("PASS "+name);}
void Fails(Action body){try{body();}catch(ContentException){return;}throw new Exception("Expected content rejection.");}
void At(int x,int y){world.State.X=x;world.State.Y=y;world.State.Z=p.Map.Get(x,y).Z;}
Reply Use(string id)=>world.Handle(new(){Type="interact",TargetId=id});
bool Reaches(int x,int y,int tx,int ty){var q=new Queue<(int x,int y)>();var seen=new HashSet<(int,int)>{(x,y)};q.Enqueue((x,y));while(q.TryDequeue(out var at)){if(at==(tx,ty))return true;foreach(var d in new[]{(1,0),(-1,0),(0,1),(0,-1)})if(world.CanStep(at.x,at.y,d.Item1,d.Item2)&&seen.Add((at.x+d.Item1,at.y+d.Item2)))q.Enqueue((at.x+d.Item1,at.y+d.Item2));}return false;}
MapObject Obj(string id)=>p.Map.Objects.First(o=>o.Id==id);
Test("authored 256-square island, 15 residents, 8 roofs and two dungeon floors",()=>{Assert(p.Map.Width==256&&p.Map.Height==256);Assert(p.Map.Objects.Count(o=>o.Kind=="npc")==15&&p.Map.Roofs.Count==8);Assert(p.Map.Regions.Count(r=>r.Kind=="dungeon")==2&&p.Map.Objects.Count(o=>o.Kind=="trigger"&&o.Id.StartsWith("cellar"))==16);});
Test("all authored interactions and encounters are navigable from spawn",()=>{var issues=WorldAuthoring.NavigationIssues(p,p.Map);Assert(issues.Count==0,string.Join('\n',issues));});
Test("marked beacon approach climbs only two units per step",()=>{for(int y=58;y>46;y--)Assert(world.CanStep(88,y,0,-1),"Blocked marked road at 88,"+y);});
Test("ServUO matches every original island terrain and static tile",()=>world.VerifyEngineView());
Test("13 authored encounters preserve all five combat archetypes",()=>Assert(world.State.Combat.Enemies.Count==13&&world.State.Combat.Enemies.Select(e=>e.Kind).Distinct().Count()==5));
Test("world containers and keys initialize exactly once",()=>{int n=world.State.Items.Count;WorldSimulation.Initialize(p,world.State);Assert(world.State.Items.Count==n&&world.State.Items.Any(i=>i.Id=="world.item.cellar.key"));});
Test("town and docks are combat sanctuaries; woodland is dangerous",()=>{Assert(CombatRules.InCamp(p,70,170)&&CombatRules.InCamp(p,88,225));Assert(!CombatRules.InCamp(p,44,121));});
Test("town merchant uses placed NPC position",()=>{At(86,181);Assert(InventoryRules.MerchantReachable(p,world.State));At(44,121);Assert(!InventoryRules.MerchantReachable(p,world.State));});
Test("closed doors block movement and spell line of sight until opened",()=>{var o=Obj("town.inn.door");At(o.X,o.Y+1);Assert(!world.CanStep(o.X,o.Y+1,0,-1));Assert(!CombatRules.LineOfSight(p,o.X,o.Y+1,o.X,o.Y-1,world.State));Assert(Use(o.Id).Ok);Assert(world.CanStep(o.X,o.Y+1,0,-1));Assert(CombatRules.LineOfSight(p,o.X,o.Y+1,o.X,o.Y-1,world.State));});
Test("occupied door cannot be closed on a player",()=>{var o=Obj("town.inn.door");At(o.X,o.Y);Assert(!Use(o.Id).Ok&&WorldAuthoring.Progress(world.State,o.Id)!.Active);});
Test("distant and unknown interactions reject without mutation",()=>{At(86,181);string before=Wire.Encode(world.State);Assert(!Use("stairs.beacon").Ok&&!Use("unknown").Ok&&Wire.Encode(world.State)==before);});
Test("stairs transfer to both dungeon levels and back",()=>{At(89,46);Assert(Use("stairs.beacon").Ok&&world.State.X==200&&world.State.Y==28);At(239,44);Assert(Use("stairs.down").Ok&&world.State.Y==108);Assert(Use("stairs.lower").Ok&&world.State.Y==44);At(200,28);Assert(Use("stairs.upper").Ok&&world.State.X==89&&world.State.Y==46);});
Test("closed lower gate prevents reaching the boss chamber",()=>Assert(!Reaches(200,108,239,120)));
Test("gate is controlled by its referenced lever",()=>{At(232,122);Assert(!Use("cellar.gate").Ok);At(226,120);Assert(Use("cellar.lever").Ok&&WorldAuthoring.Progress(world.State,"cellar.gate")!.Active);});
Test("the opened gate still leaves the final chamber key-locked",()=>Assert(!Reaches(200,108,239,120)));
Test("locked door requires the physical carried key identity",()=>{var o=Obj("cellar.lock");At(o.X-1,o.Y);Assert(!Use(o.Id).Ok);At(215,28);var r=world.Handle(new(){Type="transfer",ItemId="world.item.cellar.key",Destination="bag",X=80,Y=150});Assert(r.Ok);At(o.X-1,o.Y);Assert(Use(o.Id).Ok);});
Test("lever and carried key together make the boss chamber reachable",()=>Assert(Reaches(200,108,239,120)));
Test("key identity cannot be sold or merged away",()=>{At(86,181);string before=Wire.Encode(world.State);var regular=world.State.Items.First(i=>i.Definition.EndsWith("sealed-scroll")&&i.Id!="world.item.cellar.key");Assert(!world.Handle(new(){Type="trade",Destination="sell",ItemId="world.item.cellar.key",Amount=1}).Ok);Assert(!world.Handle(new(){Type="transfer",Destination="stack",ItemId="world.item.cellar.key",TargetId=regular.Id}).Ok);Assert(Wire.Encode(world.State)==before);});
Test("traps apply damage once per recharge and discoveries only once",()=>{At(213,122);int hp=world.State.Combat.Health;WorldSimulation.Enter(p,world.State);Assert(world.State.Combat.Health<hp);int hit=world.State.Combat.Health;WorldSimulation.Enter(p,world.State);Assert(world.State.Combat.Health==hit);At(42,124);WorldSimulation.Enter(p,world.State);int n=world.State.Journal.Count;WorldSimulation.Enter(p,world.State);Assert(world.State.Journal.Count==n&&world.State.World.Visited.Contains("discover.woods"));});
Test("placed healer recovers health and statuses",()=>{At(70,192);world.State.Combat.Status.PoisonUntil=10;Assert(Use("npc.elin").Ok&&world.State.Combat.Health==100&&world.State.Combat.Status.PoisonUntil==0);});
Test("world references, unknown loot and duplicate IDs reject",()=>{var m=p.Map.Clone();m.Objects[0].Id=m.Objects[1].Id;Fails(()=>p.ValidateMap(m));m=p.Map.Clone();m.Objects.First(o=>o.Kind=="lever").TargetId="bad";Fails(()=>p.ValidateMap(m));m=p.Map.Clone();m.Objects.First(o=>o.Kind=="container").Loot[0].Definition="unknown";Fails(()=>p.ValidateMap(m));});
Test("encounters cannot be authored inside a sanctuary",()=>{var m=p.Map.Clone();var e=m.Objects.First(o=>o.Kind=="encounter");e.X=86;e.Y=181;Fails(()=>p.ValidateMap(m));});
Test("brush, rectangle, flood fill and elevation preserve valid spawn",()=>{var m=p.Map.Clone();MapWorkshop.Terrain(m,m.Spawn.X,m.Spawn.Y,1,"greyhaven.terrain.stone");Assert(m.Get(m.Spawn.X,m.Spawn.Y).Terrain==p.Map.Get(m.Spawn.X,m.Spawn.Y).Terrain);MapWorkshop.Rectangle(m,84,181,82,180,"greyhaven.terrain.dirt");Assert(m.Get(82,180).Terrain.EndsWith("dirt"));MapWorkshop.Elevation(m,m.Spawn.X,m.Spawn.Y,0,2);Assert(m.Spawn.Z==2);m.Get(1,1).Terrain="greyhaven.terrain.dirt";MapWorkshop.Flood(m,1,1,"greyhaven.terrain.stone");Assert(m.Get(1,1).Terrain.EndsWith("stone"));});
Test("prefabs create floors, passable door and a roof group transactionally",()=>{var doc=new MapWorkshop(p,p.Map);int roofs=doc.Map.Roofs.Count;doc.Change(m=>MapWorkshop.Prefab(m,95,135,"cottage"),true);Assert(doc.Map.Roofs.Count==roofs+1&&doc.Map.Objects.Last().Kind=="door");string after=Wire.Encode(doc.Map);Assert(doc.Undo()&&doc.Map.Roofs.Count==roofs);Assert(doc.Redo()&&Wire.Encode(doc.Map)==after);Fails(()=>doc.Change(m=>MapWorkshop.Prefab(m,255,255,"inn"),true));Assert(Wire.Encode(doc.Map)==after);});
Test("navigation validator identifies an isolated authored interaction",()=>{var m=p.Map.Clone();m.Get(1,1).Terrain="greyhaven.terrain.stone";m.Objects.Add(new(){Id="isolated",Kind="sign",Name="Unreachable",X=1,Y=1});p.ValidateMap(m);Assert(WorldAuthoring.NavigationIssues(p,m).Any(i=>i.Contains("isolated")));});
Test("full island and dynamic progress round-trip through campaign saves",()=>{string home=Path.Combine(Path.GetTempPath(),"greyhaven-world-"+Guid.NewGuid());try{var store=new CampaignStore(home,"slot1");At(86,181);store.Write(p,world.State,"manual");var save=store.Read("manual");CampaignStore.Validate(p,save);int n=world.State.Items.Count;var visited=world.State.World.Visited.ToList();world.Restore(save);Assert(world.State.World.Objects.First(o=>o.Id=="cellar.gate").Active&&world.State.Items.Count==n&&world.State.World.Visited.SequenceEqual(visited));}finally{Directory.Delete(home,true);}});
Test("forged object timers and trigger IDs reject saved progress",()=>{var s=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!;s.World.Objects[0].ReadyAt=double.PositiveInfinity;Fails(()=>WorldAuthoring.ValidateProgress(p,s));s=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!;s.World.Visited.Add("unknown");Fails(()=>WorldAuthoring.ValidateProgress(p,s));});
Console.WriteLine($"{count} island, gameplay-object and editor checks passed.");
